import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query'; import { availabilityApi } from '../api/availability'; import type { CreateDoctorAvailabilityInput,UpdateDoctorAvailabilityInput } from '../types/models'; export function useDoctorAvailability(id?:string){return useQuery({queryKey:['availability',id],queryFn:()=>availabilityApi.list(id!),enabled:Boolean(id)})} export function useCreateDoctorAvailability(id:string){const qc=useQueryClient();return useMutation({mutationFn:(p:CreateDoctorAvailabilityInput)=>availabilityApi.create(id,p),onSuccess:()=>{void qc.invalidateQueries({queryKey:['availability',id]});void qc.invalidateQueries({queryKey:['doctors']})}})} export function useUpdateDoctorAvailability(id:string){const qc=useQueryClient();return useMutation({mutationFn:(v:{availabilityId:string;payload:UpdateDoctorAvailabilityInput})=>availabilityApi.update(v.availabilityId,v.payload),onSuccess:()=>{void qc.invalidateQueries({queryKey:['availability',id]});void qc.invalidateQueries({queryKey:['doctors']})}})} export function useDeleteDoctorAvailability(id:string){const qc=useQueryClient();return useMutation({mutationFn:(availabilityId:string)=>availabilityApi.remove(availabilityId),onSuccess:()=>{void qc.invalidateQueries({queryKey:['availability',id]});void qc.invalidateQueries({queryKey:['doctors']})}})}
